import { callGrok, GROK_SMART } from '@/lib/grok'

/**
 * Content Engine — AI script drafting. New isolated feature; imports only
 * generic, feature-agnostic infra (@/lib/grok, same class of dependency as
 * @/lib/db) — nothing from src/lib/monitor/* is touched or imported.
 *
 * Fixed per-niche template (identity/wardrobe/scene-lock) is NOT generated by
 * the LLM — those are business decisions enforced in code, matching this
 * project's "structural guarantee, not just prompted" pattern. The LLM only
 * writes the joke: scene_events[] + duration_seconds.
 */

export interface Person {
  id: string
  role: string
  appearance: string
  wardrobe: string
}

export interface SceneEvent {
  timestamp: string
  speaker: string // a Person.id, or "none"
  line: string | null
  delivery: string | null
  action: string
}

export interface Script {
  duration_seconds: number
  people: Person[]
  environment: string
  lighting: string
  scene_events: SceneEvent[]
  negative_prompt: string
}

const PEOPLE: Person[] = [
  {
    id: 'female_subject',
    role: 'main subject on camera, sitting in the driver seat of a luxury sports car with the window rolled down',
    appearance: 'identity locked to the reference photos provided as separate images -- same face, hair, skin tone',
    wardrobe: 'red blazer over a white lace top, small earrings',
  },
  {
    id: 'cameraman',
    role: 'interviewer, standing just outside the car window, fully out of frame',
    appearance: 'never visible on screen -- no face, no body, no hands',
    wardrobe: 'n/a -- not in frame',
  },
]
const ENVIRONMENT =
  'Interior of a luxury sports car parked on an upscale Dubai street, palm trees and modern buildings visible through the windshield, bright daylight.'
const LIGHTING = 'Bright, direct natural sunlight illuminating the car interior and her face.'
const NEGATIVE_PROMPT =
  'no smooth gimbal motion, no cinematic stabilization, no professional studio lighting, no beauty filter, ' +
  'no AI skin smoothing, extra fingers, extra limbs, warped hands, morphing face, identity drift, camera zoom, ' +
  'camera pan, camera cut, wardrobe change mid-scene, steering wheel or dashboard moving position, ' +
  'car interior changing, blurry, low resolution, watermark, text overlay'

export const PERSONA = `She is confident, witty, and a little flirty -- deadpan delivery, sarcastic
punchlines, teases the interviewer and her male audience good-naturedly. Humor targets car
brands, driving habits, and client stereotypes (never race, religion, or other protected
traits). Buildup -> short pause/beat if needed -> punchline that lands ON HER, delivered
with a laugh or smirk.`

// Few-shot: real, user-approved examples (their own words).
