const SYSTEM_PROMPT = `You write short comedic dialogue scripts for a car-rental social media ad
format: a woman sits in the driver's seat of a rental car with the window down, an unseen
interviewer standing outside asks her things, she answers with a joke/punchline.

PERSONA: ${PERSONA}

OUTPUT FORMAT: a single JSON object with exactly two keys:
{
  "duration_seconds": <number>,
  "scene_events": [
    { "timestamp": "0:00-0:01.2", "speaker": "cameraman" | "female_subject" | "none",
      "line": "<spoken words, or null>", "delivery": "<tone/manner, or null>",
      "action": "<physical action/expression at this beat -- always present>" }
  ]
}

RULES:
1. "speaker" must be exactly "cameraman", "female_subject", or "none" -- nothing else.
2. Timestamps are contiguous and increasing, starting at "0:00", ending exactly at
   duration_seconds. No gaps, no overlaps.
3. Realistic speech pace: ~140-170 words per minute total across all spoken lines. Do not
   cram long lines into a short timestamp -- unnaturally fast delivery reads as broken lip
   sync. Compute duration from the actual word count, don't guess.
4. Target total duration 8-13 seconds. Only go longer if the joke genuinely needs it, and
   never exceed 15 seconds.
5. Default to a real back-and-forth: the cameraman should ask a follow-up question or drop a
   reactive remark between her lines, not just fire one opening question and go silent for
   the rest of the clip. A single speaker may hold two consecutive beats only when genuinely
   mid-sentence (e.g. listing items, or a short pause-then-continue) -- never as the default
   shape of the whole script. Aim for at least 2 cameraman turns (opening question + at least
   one follow-up/reaction) on anything 8s or longer.
6. The LAST spoken beat must be "female_subject" delivering the punchline. It's fine to end
   with one final "none" reaction beat after it.
7. Every beat needs an "action" describing her physical performance at that moment (even
   "none" beats). When she is NOT the speaker, her action must make clear she is silently
   listening (e.g. "mouth closed and still, listening") -- she must never appear to be
   speaking during the interviewer's lines.
8. Keep humor about car brands, driving habits, or client behavior -- like the examples.
   Never target race, religion, nationality, or other protected traits.
9. Output ONLY the JSON object. No commentary, no markdown fences.`

interface GrokDraft {
  duration_seconds: number
  scene_events: SceneEvent[]
}

export interface ScriptWarning {
  message: string
}

/** Structural check mirroring the copy-paste-v2 misattribution fix: catches a
 * speaker id the renderer wouldn't recognise before it ever reaches a prompt. */
function validate(draft: GrokDraft): ScriptWarning[] {
  const warnings: ScriptWarning[] = []
  const validSpeakers = new Set(['cameraman', 'female_subject', 'none'])
  for (const e of draft.scene_events) {
    if (!validSpeakers.has(e.speaker)) warnings.push({ message: `Unknown speaker "${e.speaker}" at ${e.timestamp}` })
  }
  const last = draft.scene_events.filter(e => e.line).pop()
  if (!last || last.speaker !== 'female_subject') {
    warnings.push({ message: 'Last spoken line is not female_subject -- punchline may not land on her' })
  }
  const totalWords = draft.scene_events
    .filter(e => e.line)
    .reduce((n, e) => n + (e.line as string).trim().split(/\s+/).length, 0)
  const wpm = totalWords / (draft.duration_seconds / 60)
  if (wpm > 190) warnings.push({ message: `Pacing looks too fast: ~${Math.round(wpm)} wpm (target 140-170)` })
  if (wpm < 100 && totalWords > 3) warnings.push({ message: `Pacing looks too slow: ~${Math.round(wpm)} wpm (target 140-170)` })
  if (draft.duration_seconds > 15) warnings.push({ message: `Duration ${draft.duration_seconds}s exceeds the 15s cap` })
  return warnings
}

export async function generateScript(topic: string): Promise<{ script: Script; warnings: ScriptWarning[] }> {
  if (!topic.trim()) throw new Error('topic is required')

  const userPrompt = `TOPIC / BRIEF: ${topic}

Here are two real, approved examples of the exact format and style (for reference only,
write a NEW script, don't reuse these):

EXAMPLE 1 -- a short clip where she carries the build-up alone after one question. This is
the EXCEPTION, only for a tight joke that doesn't need a follow-up:
${JSON.stringify(STYLE_EXAMPLES[0], null, 2)}

EXAMPLE 2 -- a real back-and-forth with multiple cameraman turns. This is the DEFAULT shape
to match unless the joke is genuinely too short for it:
${JSON.stringify(STYLE_EXAMPLES[1], null, 2)}

Now write a new script for the topic above.`

  const raw = await callGrok({
    model: GROK_SMART,
    system: SYSTEM_PROMPT,
    messages: [{ role: 'user', content: userPrompt }],
    maxTokens: 2048,
    temperature: 0.9,
    json: true,
    timeoutMs: 120_000,
  })

  const draft: GrokDraft = JSON.parse(raw)
  const warnings = validate(draft)

  const script: Script = {
    duration_seconds: draft.duration_seconds,
    people: PEOPLE,
    environment: ENVIRONMENT,
    lighting: LIGHTING,
    scene_events: draft.scene_events,
    negative_prompt: NEGATIVE_PROMPT,
  }

  return { script, warnings }
}
